{"path":"work.py","content":""""Evaluate policy-controlled state transitions."""


def evaluate(request, policy):
    """Return the result of applying *request* under *policy*.

    Inputs are treated as read-only. A request is a retry only when its
    ``retry`` field is truthy; retries require a non-boolean integer attempt
    count within the policy's half-open retry range.
    """
    edge_key = f"{request.get('from')}>{request.get('to')}"
    edge = policy.get("edges", {}).get(edge_key)

    if edge is None:
        return {"ok": False, "value": None, "reason": "blocked"}

    if "role" in edge and request.get("role") != edge["role"]:
        return {"ok": False, "value": None, "reason": "permission"}

    if request.get("retry"):
        attempts = request.get("attempts")
        retry_limit = policy.get("retry_limit")
        valid_attempts = (
            isinstance(attempts, int)
            and not isinstance(attempts, bool)
            and isinstance(retry_limit, int)
            and not isinstance(retry_limit, bool)
            and 0 <= attempts < retry_limit
        )
        if not valid_attempts:
            return {"ok": False, "value": None, "reason": "retry_limit"}

    return {"ok": True, "value": request.get("to"), "reason": "ok"}
